              className="text-xs font-mono h-8 border-white/10 hover:border-white/20 text-neutral-200"
            >
              {isRotatingKey ? 'Rotating...' : 'Rotate Key'}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

